        detail: "Everything the Course Credit tab and Sierra say about what colleges have acted on is this old. "
          + "It refreshes only when someone re-runs the Access export by hand.",
        count: age, state: (age != null && age >= 7) ? "waiting" : "clear",
        personWaiting: false, since: newest,
